#!/usr/bin/env node
const yargs = require('yargs/yargs');
const { hideBin } = require('yargs/helpers');

yargs(hideBin(process.argv))
  .command('{{cmd_name}} <target>', 'run {{cmd_name}}', (y) => {
    return y.positional('target', { type: 'string' });
  }, (argv) => {
    console.log(`{{cmd_name}} -> ${argv.target}`);
  })
  .option('verbose', { alias: 'v', type: 'boolean' })
  .demandCommand(1)
  .strict()
  .parse();
